<?php
namespace App\Livewire\LMS\GradingScales;
use App\Models\{GradingScale,School}; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\ValidationException; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component {use AuthorizesRequests; public bool $showFormModal=false; public ?int $editingId=null; public string $grade='',$minimum='',$maximum='',$remark='',$sequence='0'; public function mount():void{$this->authorize('viewAny',GradingScale::class);} public function create():void{$this->authorize('create',GradingScale::class);$this->resetForm();$this->showFormModal=true;} public function edit(GradingScale $scale):void{$this->authorize('update',$scale);$this->editingId=$scale->id;$this->grade=$scale->grade;$this->minimum=$scale->minimum;$this->maximum=$scale->maximum;$this->remark=$scale->remark??'';$this->sequence=$scale->sequence;$this->showFormModal=true;} public function save():void{$scale=$this->editingId?GradingScale::findOrFail($this->editingId):null;$this->authorize($scale?'update':'create',$scale??GradingScale::class);try{$d=$this->validate(['grade'=>['required','string','max:20'],'minimum'=>['required','numeric','min:0','max:100'],'maximum'=>['required','numeric','min:0','max:100','gte:minimum'],'remark'=>['nullable','string','max:255'],'sequence'=>['required','integer','min:0']]);$overlap=GradingScale::where('school_id',School::query()->value('id'))->where('minimum','<=',$d['maximum'])->where('maximum','>=',$d['minimum'])->when($scale,fn($q)=>$q->whereKeyNot($scale->id))->exists();if($overlap){$this->addError('minimum','This range overlaps an existing grade.');return;}GradingScale::updateOrCreate(['id'=>$scale?->id],['school_id'=>School::query()->value('id'),...$d]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title('Grade scale saved')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save grade scale')->error()->show();}} public function closeModal():void{$this->showFormModal=false;$this->resetForm();} private function resetForm():void{$this->reset(['editingId','grade','minimum','maximum','remark','sequence']);$this->sequence='0';$this->resetValidation();} public function render(){return view('livewire.lms.grading-scales.index',['scales'=>GradingScale::where('school_id',School::query()->value('id'))->orderBy('sequence')->get()]);}}
